<script module lang="ts">
/**
 * A default command plus a menu of variants (`design/components/split-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext } from 'svelte'

import * as zag from '@zag-js/menu'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  agentPress,
  attributes,
  chainHandlers,
  chooseMenuEntry,
  followHighlight,
  joinSlot,
  menuChoices,
  mergeParts,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
  type IconRole,
  type LawfulVariants,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/split-button.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Kbd from '../structure/Kbd.svelte'
import SplitButtonSubmenu from './SplitButtonSubmenu.svelte'
import type { MenuEntry } from '../overlays/Menu.svelte'

export interface SplitButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'neutral' | 'accent'
}

export type SplitButtonAppearance = LawfulVariants<SplitButtonGrid>

export interface SplitButtonProps {
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  /**
   * Disables the whole group, because the halves never differ.
   */
  disabled?: boolean
  /**
   * Menu entries exactly as `menu.md` defines them, with every entry kind supported.
   */
  entries: MenuEntry[]
  /**
   * A leading icon on the primary half (as in Button).
   */
  icon?: IconRole
  /**
   * The primary half's visible text, as in Button, truncated with an ellipsis on overflow.
   */
  label: string
  /**
   * Shows the spinner in the primary half's icon slot, following the conventions' loading rule,
   * and the layout stays the same. The chevron is disabled too. One running command is the whole
   * group's state, and starting a variant while it runs would be the double-submit bug Button
   * prevents, at group level.
   */
  loading?: boolean
  /**
   * The chevron half's accessible name ("More resolve options"). It is `iconOnly`, and an
   * unnamed second button would be an unexplained tab stop. Required, because the member has no
   * built-in text (as with PasswordInput's `toggleLabel`).
   */
  menuLabel: string
  /**
   * The primary half's handler. Disconnected while `loading` (Button's double-submit rule).
   */
  onClick?: (event: MouseEvent) => void
  /**
   * The menu half's presentation, as in Menu (`menu.md`; the conventions' sheet presentation).
   * `'auto'` shows the panel as a sheet below `30rem`, and `'popover'` keeps the popper. The
   * control group itself never changes, because the halves are Buttons, and Buttons have no
   * phone-specific form.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}
</script>

<script lang="ts">
let {
  defaultOpen,
  disabled = false,
  entries,
  icon,
  label: labelOwn,
  loading = false,
  menuLabel,
  onClick: onClickOwn,
  presentation = 'auto',
  size = 'md',
  tone = 'accent',
  variant = 'solid',
}: SplitButtonProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const onClick = $derived(chainHandlers(onClickOwn, joined.passed['onClick']))
let panel = $state<HTMLElement | null>(null)
let primary = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const flat = $derived(
  entries.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen,
      disabled: disabled || loading,
      positioning: { placement: 'bottom-end', gutter: 2 },
      onSelect: (details) => {
        flat.forEach(
          (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
setContext('polymorph:SplitButton', {
  get api() {
    return api
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect1, { watch: () => api.highlightedValue })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'SplitButton',
    element: () => primary,
    state: () => ({
      disabled: disabled,
      loading: loading,
      open: api.open,
      entries: menuChoices(entries),
    }),
    actions: {
      press: () => agentPress(primary),
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (loading) throw new Error('A command is running; its variants wait until it ends.')
            if (chooseMenuEntry(entries, value) && api.open) api.setOpen(false)
          })(),
      },
      open: () =>
        (() => {
          if (loading) throw new Error('A command is running; its variants wait until it ends.')
          api.setOpen(true)
        })(),
      close: () => api.setOpen(false),
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    class={styles.group}
    data-variant={variant}
    data-tone={tone}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-member="split-button"
    ><button
      bind:this={primary}
      class={styles.primary}
      type="button"
      {disabled}
      aria-busy={(loading) ? true : undefined}
      data-variant={variant}
      data-tone={tone}
      data-size={size}
      data-disabled={(disabled) ? '' : undefined}
      data-state={(loading) ? 'loading' : undefined}
      onclick={(event) => { if (!loading) onClick?.(event) }}
      >{#if loading
        }<span class={styles.spinner}><Icon name="loading" {size} /></span
      >{:else if icon !== undefined
        }<span class={styles.glyph}><Icon name={icon} {size} /></span
      >{/if
      }<span class={styles.label}>{label}</span
    ></button
    ><span class={styles.seam} aria-hidden="true"></span
    ><button
      {...attributes(api.getTriggerProps())}
      class={styles.chevron}
      disabled={disabled || loading}
      aria-label={menuLabel}
      data-variant={variant}
      data-tone={tone}
      data-size={size}
      data-disabled={(disabled) ? '' : undefined}
      data-icon-only=""
      ><Icon name="expand" {size}
    /></button
  ></span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
          class={styles.content}
          style:--radix-dropdown-menu-content-available-height={'var(--available-height)'}
          style:--radix-dropdown-menu-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          data-member="split-button"
          >{#each entries as entry, index (index)
            }{#if entry.kind === 'separator'
              }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
            >{:else if entry.kind === 'label'
              }<div class={styles.groupLabel}>{entry.label}</div
            >{:else if entry.kind === 'checkbox'
              }<div
                {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={[styles.item, styles.checkbox]}
                tabindex="-1"
                ><span class={styles.check}
                  >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.rowLabel}>{entry.label}</span
              ></div
            >{:else if entry.kind === 'submenu'
              }<SplitButtonSubmenu {entry}
            />{:else
              }<div
                {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={styles.item}
                data-tone={entry.tone ?? 'neutral'}
                tabindex="-1"
                >{#if entry.icon !== undefined
                  }<span class={styles.rowGlyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={styles.rowLabel}>{entry.label}</span
                >{#if entry.kbd !== undefined
                  }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                >{/if
              }</div
            >{/if
          }{/each
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          tabindex="-1"
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
            class={styles.sheetList}
            hidden={undefined}
            data-member="split-button"
            >{#each flat as entry, index (index)
              }{#if entry.kind === 'separator'
                }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
              >{:else if entry.kind === 'label'
                }<div class={styles.groupLabel}>{entry.label}</div
              >{:else if entry.kind === 'checkbox'
                }<div
                  {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={[styles.item, styles.checkbox]}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.rowLabel}>{entry.label}</span
                ></div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={styles.item}
                  data-tone={entry.tone ?? 'neutral'}
                  tabindex="-1"
                  >{#if entry.icon !== undefined
                    }<span class={styles.rowGlyph}><Icon name={entry.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.rowLabel}>{entry.label}</span
                  >{#if entry.kbd !== undefined
                    }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                  >{/if
                }</div
              >{/if
            }{/each
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
